// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.speakerimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport kotlin.math.sqrt/** * NOUS — Speaker Recognition Engine (§8 Speaker Recognition). * * Identifies who is speaking from audio. Two-tier architecture: * *  1. **Primary**: ECAPA-TDNN (ONNX, 80 MB) → 192-dim voice embedding. *     State-of-the-art speaker recognition (EER ~1.5%). Used when the ONNX *     model is downloaded and on-device. * *  2. **Fallback**: MFCC mean+variance (lightweight, pure Kotlin) → 52-dim *     embedding. Used when ONNX Runtime is unavailable or the ECAPA model *     isn't downloaded. EER ~8% — good enough for "is this the owner?" *     but not for distinguishing similar voices. * * ## Pipeline (§8) * * ``` * Audio (3+ seconds) *     ↓ * Feature extraction (MFCC, 26-dim, 10ms frames) *     ↓ * ECAPA-TDNN inference (ONNX)         ← primary *     ↓ (if ONNX unavailable) * MFCC mean+variance embedding         ← fallback *     ↓ * 192-dim (or 52-dim) voice embedding *     ↓ * Cosine similarity vs enrolled prints *     ↓ * Match (> 0.7) → identified speaker * No match → unknown speaker * ``` * * ## Enrollment (§8 Voice Print Enrollment) * * To enroll a speaker, NOUS records 5 audio samples (3 s each), extracts * embeddings from each, and **averages** them for a stable voice print. * Averaging reduces the impact of within-speaker variation (different * moods, microphones, etc.). * * ## Multi-user (§25 Q6) * * Up to 5 enrolled speakers per device. Each family member can enroll; * NOUS identifies who is speaking and adapts persona / context accordingly. * [SpeakerConfig.maxEnrolledSpeakers] enforces this limit at enrollment time. * * ## Privacy (§8 Privacy) * *  - Voice prints stored encrypted (SQLCipher via [VoicePrintStore]). *  - Never synced to cloud. *  - User can delete prints anytime. *  - Strangers' voices NOT stored — only checked against enrolled prints. * * ## Testability * * [EcapaTdnnBackend] is an interface — tests inject a fake. The MFCC path * is fully testable in pure Kotlin (no native deps). [VoicePrintStore] is * also an interface — tests use [InMemoryVoicePrintStore]. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§8 Speaker Recognition, §25 Q6 multi-user</a> */class SpeakerRecognitionEngine(    private val mfccExtractor: MfccFeatureExtractor,    private val ecapaBackend: EcapaTdnnBackend?,    private val store: VoicePrintStore,    private val config: SpeakerConfig = SpeakerConfig(),    private val inferenceDispatcher: CoroutineDispatcher,) {    /**     * Enroll a new speaker from multiple audio samples.     *     * @param speakerId    unique identifier (UUID or user-chosen name).     * @param displayName  human-readable name shown in UI.     * @param audioSamples list of audio recordings ([config.enrollmentSamples]     *                     required, each [config.sampleDurationSec] long).     * @return the enrolled [VoicePrint], or null if enrollment failed (too     *         few samples, audio too short, or max speakers reached).     */    suspend fun enroll(        speakerId: String,        displayName: String,        audioSamples: List<ShortArray>,    ): VoicePrint? = withContext(inferenceDispatcher) {        if (audioSamples.size < config.enrollmentSamples) {            Timber.tag(TAG).w("Enrollment failed: need ${config.enrollmentSamples} samples, got ${audioSamples.size}.")            return@withContext null        }        if (store.count() >= config.maxEnrolledSpeakers && store.load(speakerId) == null) {            Timber.tag(TAG).w("Enrollment failed: max ${config.maxEnrolledSpeakers} speakers already enrolled.")            return@withContext null        }        // Extract embedding from each sample, then average.        val embeddings = audioSamples.mapNotNull { audio -> extractEmbedding(audio) }        if (embeddings.isEmpty()) {            Timber.tag(TAG).w("Enrollment failed: no embeddings extracted (audio too short?).")            return@withContext null        }        val avgEmbedding = averageEmbeddings(embeddings)        val source = if (ecapaBackend != null) ExtractorSource.ECAPA_TDNN else ExtractorSource.MFCC        val print = VoicePrint(            speakerId = speakerId,            embedding = avgEmbedding,            embeddingDim = avgEmbedding.size,            displayName = displayName,            source = source,        )        store.save(print)        Timber.tag(TAG).i("Enrolled speaker '$displayName' (id=$speakerId, dim=${print.embeddingDim}, source=$source).")        print    }    /**     * Identify the speaker from audio.     *     * @param audio input audio (must be at least [config.minAudioSeconds] long).     * @return match result with the best speaker ID (or null if no match),     *         similarity score, and confidence bucket.     */    suspend fun identify(audio: ShortArray): SpeakerMatchResult = withContext(inferenceDispatcher) {        val minSamples = config.minAudioSeconds * AudioCapturePipeline.SAMPLE_RATE        if (audio.size < minSamples) {            Timber.tag(TAG).w("Identify: audio too short (${audio.size} < $minSamples samples).")            return@withContext SpeakerMatchResult(                matchedSpeakerId = null,                similarity = 0f,                confidence = SpeakerConfidence.LOW,                allScores = emptyList(),                source = if (ecapaBackend != null) ExtractorSource.ECAPA_TDNN else ExtractorSource.MFCC,            )        }        val queryEmbedding = extractEmbedding(audio)            ?: return@withContext SpeakerMatchResult(                matchedSpeakerId = null,                similarity = 0f,                confidence = SpeakerConfidence.LOW,                allScores = emptyList(),                source = if (ecapaBackend != null) ExtractorSource.ECAPA_TDNN else ExtractorSource.MFCC,            )        val enrolledPrints = store.loadAll()        if (enrolledPrints.isEmpty()) {            return@withContext SpeakerMatchResult(                matchedSpeakerId = null,                similarity = 0f,                confidence = SpeakerConfidence.LOW,                allScores = emptyList(),                source = queryEmbedding.source(),            )        }        // Compute cosine similarity to every enrolled print.        val scores = enrolledPrints.map { print ->            val sim = cosineSimilarity(queryEmbedding, print.embedding)            SpeakerScore(print.speakerId, print.displayName, sim)        }.sortedByDescending { it.similarity }        val best = scores.first()        val source = queryEmbedding.source()        val matchedSpeakerId = if (best.similarity >= config.matchThreshold) {            // Update last-matched stats.            val updated = enrolledPrints.first { it.speakerId == best.speakerId }.copy(                lastMatchedAt = System.currentTimeMillis(),                matchCount = enrolledPrints.first { it.speakerId == best.speakerId }.matchCount + 1,            )            store.save(updated)            best.speakerId        } else null        val confidence = SpeakerConfidence.fromSimilarity(            similarity = best.similarity,            mediumThreshold = config.matchThreshold,        )        SpeakerMatchResult(            matchedSpeakerId = matchedSpeakerId,            similarity = best.similarity,            confidence = confidence,            allScores = scores,            source = source,        )    }    /** Delete a speaker's voice print. */    suspend fun deleteSpeaker(speakerId: String): Boolean = store.delete(speakerId)    /** Delete all voice prints (Settings → Privacy → Clear voice data). */    suspend fun deleteAll(): Int = store.deleteAll()    /** Get all enrolled speakers (for UI listing). */    suspend fun listEnrolled(): List<VoicePrint> = store.loadAll()    // ──────────────────────────────────────────────────────────────────────    /**     * Extract an embedding from audio using the best available backend.     *     * ECAPA-TDNN if available (192-dim); MFCC fallback otherwise (52-dim).     */    private fun extractEmbedding(audio: ShortArray): FloatArray? {        // 1. Try ECAPA-TDNN (primary).        val ecapa = ecapaBackend        if (ecapa != null) {            val mfccFrames = mfccExtractor.extractFrames(audio)            if (mfccFrames.isEmpty()) return null            val ecapaEmbedding = runCatching { ecapa.infer(mfccFrames) }                .onFailure { Timber.tag(TAG).w("ECAPA-TDNN inference failed, falling back to MFCC.", it) }                .getOrNull()            if (ecapaEmbedding != null) return ecapaEmbedding        }        // 2. Fallback to MFCC mean+variance embedding (52-dim).        val mfccEmbedding = mfccExtractor.extractEmbedding(audio)        return mfccEmbedding    }    /** Average multiple embeddings into one (used during enrollment). */    private fun averageEmbeddings(embeddings: List<FloatArray>): FloatArray {        require(embeddings.isNotEmpty()) { "Cannot average empty list" }        val dim = embeddings[0].size        val avg = FloatArray(dim)        for (emb in embeddings) {            require(emb.size == dim) { "Embedding dim mismatch: ${emb.size} != $dim" }            for (i in 0 until dim) avg[i] += emb[i]        }        for (i in 0 until dim) avg[i] /= embeddings.size        return avg    }    private companion object {        private const val TAG = "SpeakerRecognition"        /** Determine the source of an embedding based on its dimensionality. */        fun FloatArray.source(): ExtractorSource =            if (size == SpeakerConfig.ECAPA_EMBEDDING_DIM) ExtractorSource.ECAPA_TDNN            else ExtractorSource.MFCC    }    // ──────────────────────────────────────────────────────────────────────    /**     * Compute cosine similarity between two vectors: (a·b) / (|a| × |b|).     *     * Returns a float in [-1, 1]; for speaker embeddings, useful range is     * approximately [0, 1] (negative similarities are rare and usually     * indicate a bug).     */    fun cosineSimilarity(a: FloatArray, b: FloatArray): Float {        require(a.size == b.size) { "Vector dim mismatch: ${a.size} != ${b.size}" }        var dot = 0.0        var normA = 0.0        var normB = 0.0        for (i in a.indices) {            dot += a[i] * b[i]            normA += a[i] * a[i]            normB += b[i] * b[i]        }        val denom = sqrt(normA) * sqrt(normB)        if (denom == 0.0) return 0f        return (dot / denom).toFloat()    }}// ──────────────────────────────────────────────────────────────────────────/** * ONNX Runtime backend for ECAPA-TDNN speaker recognition. * * Real implementation lives in :native:ecapa (already exists as a module * skeleton). Wraps `onnxruntime-android` and runs the 80 MB ECAPA-TDNN model * to produce 192-dim speaker embeddings. * * Until :native:ecapa ships (Year 2 per §24), the [SpeakerRecognitionEngine] * uses the MFCC fallback path. Tests inject a fake backend to verify the * primary path without needing ONNX Runtime. */interface EcapaTdnnBackend {    /**     * Run ECAPA-TDNN inference on pre-computed MFCC frames.     *     * @param mfccFrames list of MFCC frames (each [numCoeffs]-dim) from     *                   [MfccFeatureExtractor.extractFrames].     * @return 192-dim speaker embedding.     * @throws Throwable if inference fails (caller catches and falls back to MFCC).     */    fun infer(mfccFrames: List<FloatArray>): FloatArray    /** Whether the ONNX model is loaded and ready. */    val isReady: Boolean    /** Release ONNX resources. */    fun release()}

